int main() {
    int x1, x2, x3;
    cin >> x1 >> x2 >> x3;

    // Sort the three positions
    int a = min({x1, x2, x3});
    int c = max({x1, x2, x3});
    int b = x1 + x2 + x3 - a - c;

    // The optimal meeting point is the median (b)
